from collections import deque

def bfs_distances(start_positions, grid_h, grid_w):
    distances = {}  # (i,j) -> min distance to any start position
    for i in range(grid_h):
        for j in range(grid_w):
            distances[(i,j)] = float('inf')

    # Multi-source BFS
    queue = deque()
    for (i, j) in start_positions:
        distances[(i,j)] = 0
        queue.append((i, j))

    while queue:
        i, j = queue.popleft()
        d = distances[(i,j)]
        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < grid_h and 0 <= nj < grid_w:
                if distances[(ni, nj)] == float('inf'):
                    distances[(ni, nj)] = d + 1
                    queue.append((ni, nj))
    return distances

